    export const getListSubscriptionChargesUrl = (spaceId: string,
    params?: ListSubscriptionChargesParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    const explodeParameters = ["status"];

    if (Array.isArray(value) && explodeParameters.includes(key)) {
      value.forEach((v) => {
        normalizedParams.append(key, v === null ? 'null' : String(v));
      });
      return;
    }

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : String(value))
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/v1/manage/spaces/${spaceId}/subscription-charges?${stringifiedParams}` : `/v1/manage/spaces/${spaceId}/subscription-charges`
}

